"""Review UI for original SVG parts and untouched native Godot frames."""
from pathlib import Path
import json, base64
ROOT=Path(__file__).resolve().parents[1]; OUT=ROOT/'artifacts'
m=json.loads((ROOT/'assets/characters/concept-rig/manifest.json').read_text())
dirs=['S','SW','W','NW','N','NE','E','SE']
style='*{box-sizing:border-box}body{margin:0;background:#252d29;color:#eadbbc;font:16px/1.5 system-ui}h1{font-size:24px;margin:24px}main{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;padding:24px}.view{background:#354139;padding:16px;border-top:2px solid #98845f}h2{font-size:18px;margin:0 0 16px}.parts{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.part{height:98px;text-align:center}.part img{height:68px;max-width:65px}.part small{display:block;font-size:10px;color:#baa98b}a{color:#e9ce9e}nav{margin:24px}@media(max-width:900px){main{grid-template-columns:repeat(2,1fr)}}@media(max-width:500px){main{grid-template-columns:1fr}}'
for body in ['male','female']:
 cells=[]
 for d in range(8):
  kit=m['views'][f'{body}_{d}']['directional_art'];bits=[]
  for key,p in kit['parts'].items():
   svg=(ROOT/p['path'].removeprefix('res://')).read_text()
   src='data:image/svg+xml;base64,'+base64.b64encode(svg.encode()).decode()
   bits.append(f'<div class="part"><img alt="{key}" src="{src}"/><small>{key}</small></div>')
  cells.append(f'<section id="d{d}" class="view"><h2>{body} · {dirs[d]} · {kit["plane"]}</h2><div class="parts">'+''.join(bits)+'</div></section>')
 (OUT/f'concept41_assets_{body}.html').write_text('<!doctype html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Chi tiết theo hướng / '+body+'</title><style>'+style+'</style><h1>0.41 / Chi tiết độc lập — trước khi ghép xương</h1><nav><a href="concept41_character_review.html">← Ghép xương & hoạt ảnh</a></nav><main>'+''.join(cells)+'</main></html>')
page='''<!doctype html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cổ Sư · Chi tiết & khớp 0.41</title>
<style>*{box-sizing:border-box}body{margin:0;background:#252d29;color:#eadbbc;font:16px/1.55 system-ui}main{max-width:1480px;margin:auto;padding:28px}h1{font-size:28px;line-height:1.25;margin:0 0 12px}p{max-width:980px;color:#c9c7b8;margin:0 0 18px}a{color:#e9ce9e}nav{display:flex;gap:20px;flex-wrap:wrap;border-bottom:1px solid #576351;padding:0 0 20px;margin-bottom:22px}.controls{display:flex;gap:14px;flex-wrap:wrap;align-items:end}label{display:grid;gap:5px;font-size:13px}select,button{font:inherit;color:#eadbbc;background:#354139;border:1px solid #8a967f;border-radius:4px;min-height:42px;padding:7px 12px}button{cursor:pointer}button:hover{background:#4a5845}:focus-visible{outline:2px solid #e7c18c;outline-offset:3px}.scrub{display:flex;align-items:center;gap:14px;margin:20px 0}input{accent-color:#cfb887;width:100%}output{white-space:nowrap;font-variant-numeric:tabular-nums}.detail{display:flex;gap:30px;align-items:center;flex-wrap:wrap}.crop{position:relative;width:300px;height:405px;overflow:hidden;background:#354139;border:1px solid #576351;flex:none}.crop img{position:absolute;width:2400px;height:1350px;max-width:none}.note{max-width:760px}.note h2{font-size:21px}.full{width:100%;height:auto;display:block;border:1px solid #576351;margin-top:22px}details{margin:18px 0}summary{cursor:pointer;font-weight:600;padding:12px 0}.legend{font-size:14px;color:#bbae91}.static{display:flex;gap:14px;flex-wrap:wrap;margin-top:20px}@media(max-width:650px){main{padding:16px}.detail{gap:16px}h1{font-size:24px}}</style>
<main><h1>Chi tiết theo hướng → ghép xương → kiểm chuyển động</h1><p>Bản 0.41: 352 asset SVG riêng cho nam/nữ ở 8 hướng. Vai nối vào ngực, tay áo và cẳng tay tách khớp; bàn tay có hình thả, nắm, đấm và thi triển. Các ảnh bên dưới được chụp từ renderer đang dùng trong game.</p>
<nav><a href="concept41_assets_male.html">Bảng chi tiết nam</a><a href="concept41_assets_female.html">Bảng chi tiết nữ</a><a href="#layers">Thân riêng & tách lớp</a><a href="concept41_constraints.json">Kiểm điểm bám</a><a href="concept41_gpu.json">Kiểm màu atlas trong Godot</a></nav>
<div class="controls"><label>Động tác<select id="action"><option value="idle">Đứng</option><option value="walk">Đi</option><option value="run">Chạy</option><option value="attack" selected>Tấn công</option><option value="defend">Phòng thủ</option><option value="cast">Thi triển</option><option value="channel">Vận công</option><option value="hit">Trúng đòn</option><option value="dash">Lướt</option><option value="death">Gục</option></select></label><label>Vũ khí<select id="weapon"><option value="sword">Kiếm</option><option value="spear">Thương</option><option value="unarmed">Tay không</option></select></label><label>Giới tính<select id="body"><option value="0">Nam</option><option value="1">Nữ</option></select></label><label>Hướng<select id="direction"></select></label><label>Lớp xem<select id="bones"><option value="0">Hình nhân vật</option><option value="1">Khớp xương</option></select></label><label>Tốc độ xem<select id="speed"><option value="8">Chậm · 8 frame/s</option><option value="24">24 frame/s</option></select></label><button id="prev" aria-label="Frame trước">←</button><button id="play">Phát</button><button id="next" aria-label="Frame sau">→</button></div>
<div class="scrub"><input id="slider" type="range" min="0" max="23" value="12" aria-label="Chọn frame"><output id="count"></output></div>
<div class="detail"><div class="crop"><img id="focus" alt="Chi tiết hướng đã chọn"></div><div class="note"><h2 id="name"></h2><p id="status"></p><p>Phần khuất tại vai, khuỷu, cổ tay và đầu gối được vẽ đầy đủ. Khi xoay khớp, mỗi chi tiết giữ kích thước và bám điểm đã định; góc sau dùng thứ tự che khuất từ sau lưng.</p><p class="legend">Đầu và chi tiết trang trí thân giữ từ concept được duyệt. Bộ mới thay các mảnh tay/chân cắt từ dáng đứng; đây vẫn là hoạt ảnh bằng khung xương, chưa phải vẽ lại từng frame. Overlay có hai thời điểm chụp cho mỗi động tác.</p><a id="original" href="">Mở ảnh gốc đủ 16 góc</a> · <a id="assets" href="concept41_assets_male.html">Xem các chi tiết của góc này</a></div></div>
<img id="full" class="full" alt="Nam và nữ ở tám hướng">
<details id="layers"><summary>Thân riêng và các bộ phận trước khi ghép</summary><p>Thân không chứa lớp tay/chân đang chuyển động. Các chi tiết tách ra dùng cùng dữ liệu và shader với nhân vật trong game.</p><img class="full" src="concept41_body.png" alt="Thân riêng"><img class="full" src="concept41_exploded.png" alt="Tách bộ phận khỏi thân"></details>
<details><summary>Đứng trung tính — kiểm tỷ lệ và tiếp giáp</summary><img class="full" src="concept41_idle.png" alt="Dáng đứng đủ 16 góc"></details><details><summary>Trong game, đổi trang phục và xưởng nhân vật</summary><img class="full" src="concept41_world_male.png" alt="Nhân vật trong thế giới"><img class="full" src="concept41_character_equipment.png" alt="Bảng nhân vật với nữ, áo crimson và giày da"><img class="full" src="concept41_studio.png" alt="Xưởng nhân vật dùng bộ chi tiết mới"></details></main>
<script>const $=id=>document.getElementById(id),dirs=['S · xuống','SW · xuống trái','W · trái','NW · lên trái','N · lên','NE · lên phải','E · phải','SE · xuống phải'];let timer=null;
dirs.forEach((name,d)=>$('direction').add(new Option(name,d)));$('direction').value='4';
function frames(){return $('action').value==='idle'?1:['walk','run','attack'].includes($('action').value)?24:8}
function update(){const action=$('action').value,count=frames(),isAttack=action==='attack';$('weapon').disabled=!isAttack;$('bones').disabled=count===1;const weapon=isAttack?$('weapon').value:'sword';$('slider').max=count-1;let n=Math.min(+$('slider').value,count-1),bones=$('bones').value==='1'&&count>1;if(bones)n=n<count/4?0:Math.floor(count/2);$('slider').value=n;const folder=`concept41_${action}_${weapon}`,url=count===1?'concept41_idle.png':bones?`${folder}_bones_${String(n).padStart(2,'0')}.png`:`${folder}/frame${String(n).padStart(3,'0')}.png`;
const d=+$('direction').value,b=+$('body').value;$('focus').src=$('full').src=$('original').href=url;$('focus').style.left=`${-d*300}px`;$('focus').style.top=`${-(105+b*370)*1.5}px`;$('count').textContent=`${n+1} / ${count}`;$('name').textContent=`${b?'Nữ':'Nam'} · ${dirs[d]} · ${$('action').selectedOptions[0].text}`;$('status').textContent=bones?'Khớp vàng là vị trí thật của vai, khuỷu, hông, đầu gối và bàn chân.':`Pha ${(n/count).toFixed(3)} · xem chậm hoặc kéo thanh để kiểm từng vị trí.`;$('assets').href=`concept41_assets_${b?'female':'male'}.html#d${d}`;}
function stop(){clearInterval(timer);timer=null;$('play').textContent='Phát'}function step(delta){const c=frames();$('slider').value=$('bones').value==='1'&&c>1?(+$('slider').value===0?c/2:0):(+$('slider').value+delta+c)%c;update()}
function play(){if(timer){stop();return}timer=setInterval(()=>step(1),1000/+$('speed').value);$('play').textContent='Dừng'}$('play').onclick=play;$('prev').onclick=()=>{stop();step(-1)};$('next').onclick=()=>{stop();step(1)};$('slider').oninput=()=>{stop();update()};for(const id of ['action','weapon','body','direction','bones'])$(id).onchange=()=>{stop();update()};$('speed').onchange=()=>{if(timer){stop();play()}};document.addEventListener('keydown',e=>{if(['SELECT','INPUT'].includes(e.target.tagName))return;if(e.key==='ArrowRight'){e.preventDefault();stop();step(1)}if(e.key==='ArrowLeft'){e.preventDefault();stop();step(-1)}if(e.code==='Space'){e.preventDefault();play()}});update();</script></html>'''
(OUT/'concept41_character_review.html').write_text(page)
print('Built directional review and two SVG authoring boards.')
